package com.example.task.model;
import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="task_templates",uniqueConstraints=@UniqueConstraint(columnNames={"workspaceId","name"})) public class TaskTemplate {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false)private Long workspaceId;private Long projectId;@Column(nullable=false)private String name;@Column(nullable=false)private String title;@Column(length=2000)private String description;@Enumerated(EnumType.STRING)private Priority priority;@Enumerated(EnumType.STRING)private RecurrenceRule recurrenceRule;private String defaultAssignee;@Column(nullable=false)private String createdBy;@Column(nullable=false)private LocalDateTime createdAt=LocalDateTime.now();
 public Long getId(){return id;}public Long getWorkspaceId(){return workspaceId;}public void setWorkspaceId(Long v){workspaceId=v;}public Long getProjectId(){return projectId;}public void setProjectId(Long v){projectId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Priority getPriority(){return priority;}public void setPriority(Priority v){priority=v;}public RecurrenceRule getRecurrenceRule(){return recurrenceRule;}public void setRecurrenceRule(RecurrenceRule v){recurrenceRule=v;}public String getDefaultAssignee(){return defaultAssignee;}public void setDefaultAssignee(String v){defaultAssignee=v;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String v){createdBy=v;}public LocalDateTime getCreatedAt(){return createdAt;}
}
